# Generated by Cursor
# Edited by Cursor (unbracketed Generallaughter / General laughter)
"""Scan for non-speech bracket content (Inaudible, Laughter, etc.) and unbracketed phrases."""

import re

from scripts.rule_normalizations import (
    NON_SPEECH_BRACKET_CONTENT,
    UNBRACKETED_NON_SPEECH_PHRASES,
)

PAREN_RE = re.compile(r"\(([^)]*)\)")
SQUARE_RE = re.compile(r"\[([^\]]*)\]")
CURLY_RE = re.compile(r"\{([^}]*)\}")
# Unbracketed: Generallaughter. or General laughter. (case-insensitive).
UNBRACKETED_NON_SPEECH_RE = re.compile(
    r"(?i)\b(?:general\s*laughter|generallaughter)\.?"
)


def _content_normalized(content: str) -> str:
    """Strip and lowercase content for allowlist match."""
    return " ".join(content.strip().rstrip(".").strip().lower().split())


def scan_turn_non_speech_brackets(
    text: str,
    path_str: str = "",
) -> list[tuple[str, int, str, str]]:
    """Scan for bracketed non-speech and unbracketed phrases (e.g. Generallaughter.); emit (rule_id, start, span, path_str)."""
    result: list[tuple[str, int, str, str]] = []
    for pattern, open_c, close_c in (
        (PAREN_RE, "(", ")"),
        (SQUARE_RE, "[", "]"),
        (CURLY_RE, "{", "}"),
    ):
        for m in pattern.finditer(text):
            content = m.group(1)
            content_norm = _content_normalized(content)
            if content_norm in NON_SPEECH_BRACKET_CONTENT:
                full_span = open_c + content + close_c
                result.append(("non_speech_brackets", m.start(), full_span, path_str))
    for m in UNBRACKETED_NON_SPEECH_RE.finditer(text):
        span = m.group(0)
        norm = " ".join(span.strip().rstrip(".").lower().split())
        if norm in UNBRACKETED_NON_SPEECH_PHRASES:
            result.append(("non_speech_brackets", m.start(), span, path_str))
    return result
